    "text": "O‘zbekistonda bir qator resurslar umumiy resurs xususiyatiga ega va ularni boshqarish muhim iqtisodiy muammo hisoblanadi. Yaylovlar. Mamlakatning katta qismini egallagan yaylovlar uzoq vaqt aniq mulk yoki foydalanish huquqlarisiz qolgani sababli ko‘plab hududlarda haddan tashqari mol boqish natijasida degradatsiyaga uchragan. 2019-yilda qabul qilingan «Yaylovlar to‘g‘risida»gi qonun yaylovlardan foydalanish huquqlarini aniq belgilash, ularni ijaraga berish va yaylov aylanishini joriy etish orqali bu muammoni hal qilishga qaratilgan – bu Demsets va Mankyu ta’kidlagan «mulk huquqlarini belgilash» yechimining amaliy namunasi. Sug‘orish suvi. Suv uzoq vaqt deyarli bepul bo‘lgani sababli (narx signali yo‘q) undan isrofgarchilik bilan foydalanilgan. Suvdan foydalanuvchilar uyushmalari (jamoa boshqaruvi), suv iste’molini hisobga olish, suv tejovchi texnologiyalarga subsidiyalar va suvdan foydalanish uchun to‘lovlarni bosqichma-bosqich joriy etish umumiy resurs muammosini yumshatishga qaratilgan. Shahar yo‘llari. Toshkentda avtomobillar sonining tez o‘sishi tirbandlikni keskin oshirdi. Pullik avtoturargohlar, jamoat transportini rivojlantirish (yangi metro liniyalari, elektrobuslar) tirbandlik tashqi samarasini kamaytirish vositalari hisoblanadi.",
